-- Dadyoom Grade 1-3 original supplementary text-linked exercises: أدوات الاستفهام, 65 safe lesson IDs.
-- The independently authored reading passages reside in each activity's content.originalText (visible to the learner).
-- No ministry source equivalence, audio delivery, or teacher sign-off is inferred. Existing learner attempts are preserved.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
CREATE TEMP TABLE g123_interrogatives_activities ON COMMIT DROP AS
SELECT grade::int,activity_order::int,activity_type::text,title::text,section::text,prompt::text,content::jsonb,answer::jsonb
FROM jsonb_to_recordset($passage$[{"grade":1,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"أكمل السؤال عن المكان: «___ قرأت مريم قصتها؟»","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"في صباح الأربعاء، دخلت مريم مكتبة المدرسة مع زميلتها. اختارت قصة عن الطيور، وجلست تقرأ قرب النافذة. قال المعلم: «من اختارت القصة؟» والجواب «مريم». ثم سأل: «أين قرأت مريم؟» والجواب «قرب النافذة». وسأل: «ماذا اختارت؟» والجواب «قصة عن الطيور». نسأل «من» عن شخص، و«أين» عن مكان، و«ماذا» عن شيء أو فعل.","didacticGrade":1,"scope":"original supplementary reading","items":[{"sentence":"___ قرأت مريم قصتها؟","options":["أين","من","ماذا"]}]},"answer":{"answers":["أين"]}},{"grade":1,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"في صباح الأربعاء، دخلت مريم مكتبة المدرسة مع زميلتها. اختارت قصة عن الطيور، وجلست تقرأ قرب النافذة. قال المعلم: «من اختارت القصة؟» والجواب «مريم». ثم سأل: «أين قرأت مريم؟» والجواب «قرب النافذة». وسأل: «ماذا اختارت؟» والجواب «قصة عن الطيور». نسأل «من» عن شخص، و«أين» عن مكان، و«ماذا» عن شيء أو فعل.","didacticGrade":1,"scope":"original supplementary reading","left":["من اختارت القصة؟","أين جلست مريم؟","ماذا اختارت مريم؟"],"right":["قصة عن الطيور","مريم","قرب النافذة"]},"answer":{"pairs":[{"left":"من اختارت القصة؟","right":"مريم"},{"left":"أين جلست مريم؟","right":"قرب النافذة"},{"left":"ماذا اختارت مريم؟","right":"قصة عن الطيور"}]}},{"grade":1,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"أي سؤال إجابته «مريم» بحسب النص؟","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"في صباح الأربعاء، دخلت مريم مكتبة المدرسة مع زميلتها. اختارت قصة عن الطيور، وجلست تقرأ قرب النافذة. قال المعلم: «من اختارت القصة؟» والجواب «مريم». ثم سأل: «أين قرأت مريم؟» والجواب «قرب النافذة». وسأل: «ماذا اختارت؟» والجواب «قصة عن الطيور». نسأل «من» عن شخص، و«أين» عن مكان، و«ماذا» عن شيء أو فعل.","didacticGrade":1,"scope":"original supplementary reading","options":["أين قرأت القصة؟","ماذا اختارت؟","من اختارت القصة؟"]},"answer":{"correct":"من اختارت القصة؟"}},{"grade":2,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"أي أداة تناسب السؤال الذي جوابه «يوم الاثنين»؟","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"يوم الاثنين، أعدَّ كريم بطاقة عن ترشيد الماء في الصف. بحث أولًا عن معلومات مع زملائه، ثم كتب تعليمات قصيرة بخط واضح. علّق البطاقة قرب المغسلة حتى يتذكر الأطفال إغلاق الصنبور. نستعمل «متى» للسؤال عن الزمن، و«كيف» عن الطريقة، و«لماذا» عن السبب. يمكن أن يكون جواب «متى؟» يوم الاثنين، وجواب «كيف؟» بالبحث ثم الكتابة، وجواب «لماذا؟» لتذكير الطلاب بإغلاق الصنبور.","didacticGrade":2,"scope":"original supplementary reading","items":[{"sentence":"___ أعدَّ كريم البطاقة؟","options":["لماذا","متى","أين"]}]},"answer":{"answers":["متى"]}},{"grade":2,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"يوم الاثنين، أعدَّ كريم بطاقة عن ترشيد الماء في الصف. بحث أولًا عن معلومات مع زملائه، ثم كتب تعليمات قصيرة بخط واضح. علّق البطاقة قرب المغسلة حتى يتذكر الأطفال إغلاق الصنبور. نستعمل «متى» للسؤال عن الزمن، و«كيف» عن الطريقة، و«لماذا» عن السبب. يمكن أن يكون جواب «متى؟» يوم الاثنين، وجواب «كيف؟» بالبحث ثم الكتابة، وجواب «لماذا؟» لتذكير الطلاب بإغلاق الصنبور.","didacticGrade":2,"scope":"original supplementary reading","left":["متى أعد كريم البطاقة؟","كيف أعد كريم البطاقة؟","لماذا علق البطاقة قرب المغسلة؟"],"right":["ليتذكر الأطفال إغلاق الصنبور","يوم الاثنين","بالبحث ثم الكتابة"]},"answer":{"pairs":[{"left":"متى أعد كريم البطاقة؟","right":"يوم الاثنين"},{"left":"كيف أعد كريم البطاقة؟","right":"بالبحث ثم الكتابة"},{"left":"لماذا علق البطاقة قرب المغسلة؟","right":"ليتذكر الأطفال إغلاق الصنبور"}]}},{"grade":2,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"أي سؤال يطلب تفسير سبب تعليق البطاقة قرب المغسلة؟","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"يوم الاثنين، أعدَّ كريم بطاقة عن ترشيد الماء في الصف. بحث أولًا عن معلومات مع زملائه، ثم كتب تعليمات قصيرة بخط واضح. علّق البطاقة قرب المغسلة حتى يتذكر الأطفال إغلاق الصنبور. نستعمل «متى» للسؤال عن الزمن، و«كيف» عن الطريقة، و«لماذا» عن السبب. يمكن أن يكون جواب «متى؟» يوم الاثنين، وجواب «كيف؟» بالبحث ثم الكتابة، وجواب «لماذا؟» لتذكير الطلاب بإغلاق الصنبور.","didacticGrade":2,"scope":"original supplementary reading","options":["متى عُلقت البطاقة؟","لماذا عُلقت البطاقة قرب المغسلة؟","أين كُتبت البطاقة؟"]},"answer":{"correct":"لماذا عُلقت البطاقة قرب المغسلة؟"}},{"grade":3,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"أي أداة تستعملها هدى لتعرف سبب صعوبة العثور على القصص؟","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"لاحظت هدى أن بعض زملائها ينسون إعادة الكتب إلى مكانها بعد القراءة. سألت: «لماذا يصعب العثور على القصص؟» فعرفت أن الرفوف غير مرتبة. ثم سألت أمينة المكتبة: «كيف ننظّم الكتب؟» واقترحت فرزها حسب الموضوع ووضع بطاقة واضحة لكل رف. بعد أسبوع، قارنت سرعة العثور على القصص. سؤال «لماذا» يطلب تفسير السبب، وسؤال «كيف» يطلب وصف الطريقة، أما «متى» فيطلب تحديد الزمن. اختيار السؤال يوجه البحث عن الدليل.","didacticGrade":3,"scope":"original supplementary reading","items":[{"sentence":"___ يصعب العثور على القصص؟","options":["كيف","لماذا","متى"]}]},"answer":{"answers":["لماذا"]}},{"grade":3,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"لاحظت هدى أن بعض زملائها ينسون إعادة الكتب إلى مكانها بعد القراءة. سألت: «لماذا يصعب العثور على القصص؟» فعرفت أن الرفوف غير مرتبة. ثم سألت أمينة المكتبة: «كيف ننظّم الكتب؟» واقترحت فرزها حسب الموضوع ووضع بطاقة واضحة لكل رف. بعد أسبوع، قارنت سرعة العثور على القصص. سؤال «لماذا» يطلب تفسير السبب، وسؤال «كيف» يطلب وصف الطريقة، أما «متى» فيطلب تحديد الزمن. اختيار السؤال يوجه البحث عن الدليل.","didacticGrade":3,"scope":"original supplementary reading","left":["لماذا صعب العثور على القصص؟","كيف نظّمت هدى الكتب؟","متى قارنت هدى سرعة العثور على القصص؟"],"right":["بعد أسبوع","لأن الرفوف كانت غير مرتبة","بفرز الكتب حسب الموضوع ووضع بطاقات"]},"answer":{"pairs":[{"left":"لماذا صعب العثور على القصص؟","right":"لأن الرفوف كانت غير مرتبة"},{"left":"كيف نظّمت هدى الكتب؟","right":"بفرز الكتب حسب الموضوع ووضع بطاقات"},{"left":"متى قارنت هدى سرعة العثور على القصص؟","right":"بعد أسبوع"}]}},{"grade":3,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"أي سؤال يساعد الباحث على معرفة الخطوات لا سبب المشكلة؟","content":{"origin":"DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030","originalText":"لاحظت هدى أن بعض زملائها ينسون إعادة الكتب إلى مكانها بعد القراءة. سألت: «لماذا يصعب العثور على القصص؟» فعرفت أن الرفوف غير مرتبة. ثم سألت أمينة المكتبة: «كيف ننظّم الكتب؟» واقترحت فرزها حسب الموضوع ووضع بطاقة واضحة لكل رف. بعد أسبوع، قارنت سرعة العثور على القصص. سؤال «لماذا» يطلب تفسير السبب، وسؤال «كيف» يطلب وصف الطريقة، أما «متى» فيطلب تحديد الزمن. اختيار السؤال يوجه البحث عن الدليل.","didacticGrade":3,"scope":"original supplementary reading","options":["لماذا تفرقت الكتب؟","متى ظهرت المشكلة؟","كيف يمكن ترتيب الكتب حسب الموضوع؟"]},"answer":{"correct":"كيف يمكن ترتيب الكتب حسب الموضوع؟"}}]$passage$::jsonb)
AS x(grade int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE candidates int; safe_candidates int; protected_count int; inserted int;
BEGIN
 IF (SELECT count(*) FROM pg_temp.g123_interrogatives_activities)<>9 OR
    (SELECT count(DISTINCT (grade,activity_order)) FROM pg_temp.g123_interrogatives_activities)<>9 OR
    EXISTS(SELECT 1 FROM pg_temp.g123_interrogatives_activities WHERE activity_type IS NULL OR answer IS NULL OR length(content->>'originalText')<150)
 THEN RAISE EXCEPTION 'Invalid nine source-linked grade-specific templates'; END IF;
 WITH found AS (
  SELECT l.id,count(a.id) FILTER(WHERE a.is_published) n,
    count(DISTINCT a.activity_order) positions,max(a.activity_order) max_order
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
  LEFT JOIN public.lesson_activities a ON a.lesson_id=l.id
  WHERE l.title='أدوات الاستفهام' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%الاستفهام%' AND l.content LIKE '%السؤال%'
  GROUP BY l.id
 )
 SELECT count(*) INTO candidates FROM found WHERE n=3 AND positions=3 AND max_order=3;
 IF candidates<>66 THEN RAISE EXCEPTION 'Expected 66 original lesson IDs with three existing activities, found %',candidates; END IF;
 SELECT count(*) INTO protected_count FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='أدوات الاستفهام' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%الاستفهام%' AND l.content LIKE '%السؤال%' AND NOT (NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id));
 IF protected_count<>1 THEN RAISE EXCEPTION 'Protected learner-history count drift, expected 1, found %', protected_count; END IF;
 SELECT count(*) INTO safe_candidates FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='أدوات الاستفهام' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%الاستفهام%' AND l.content LIKE '%السؤال%' AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF safe_candidates<>65 THEN RAISE EXCEPTION 'Expected 65 safe lesson IDs, got %',safe_candidates; END IF;
 IF EXISTS (SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Batch DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030 already inserted'; END IF;
 INSERT INTO public.lesson_activities
  (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ النص الإثرائي الموجود داخل النشاط؛ اقرأ محتوى درس بلدك مستقلًا.',
        t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN pg_temp.g123_interrogatives_activities t ON t.grade=g.grade_number
 WHERE l.title='أدوات الاستفهام' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%الاستفهام%' AND l.content LIKE '%السؤال%' AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>195 THEN RAISE EXCEPTION 'Atomic rollback: inserted % instead of 195',inserted; END IF;
 RAISE NOTICE 'DADYOOM_G123_INTERROGATIVES_195_ORIGINAL_20261030=%',inserted;
END $safe$;
COMMIT;
